package pipeline

import "sync"

// FanIn runs fn over every input concurrently and returns the results in the
// same order as the inputs. It currently deadlocks on any non-empty input.
func FanIn(inputs []int, workers int, fn func(int) int) []int {
	out := make([]int, len(inputs))
	jobs := make(chan int)
	var wg sync.WaitGroup

	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = fn(inputs[i])
			}
		}()
	}

	// Start a goroutine to close the jobs channel once all inputs are sent.
	// This prevents the main goroutine from blocking on wg.Wait() while
	// the workers are waiting for more jobs or for the channel to close.
	go func() {
		for i := range inputs {
			jobs <- i
		}
		close(jobs)
	}()

	wg.Wait()
	return out
}

using System;
using System.Collections.Generic;
using System.Linq;

public static class Ledger
{
    // Returns, for each account, the running balance after every entry, and the
    // final balance. Entries are (account, delta) in chronological order.
    // BUG: callers report that the running balances are all identical to the
    // final balance, and that AverageDelta is truncated to a whole number.
    public static (Dictionary<string, List<int>> Running, Dictionary<string, int> Final, double AverageDelta)
        Summarise(IEnumerable<(string Account, int Delta)> entries)
    {
        var totals = new Dictionary<string, int>();
        var running = new Dictionary<string, List<int>>();

        foreach (var e in entries)
        {
            if (!totals.ContainsKey(e.Account))
            {
                totals[e.Account] = 0;
                running[e.Account] = new List<int>();
            }
            totals[e.Account] += e.Delta;
            running[e.Account].Add(totals[e.Account]);
        }

        var deltas = entries.Select(e => e.Delta).ToList();
        double average = 0;
        if (deltas.Count > 0)
        {
            average = deltas.Sum(d => (double)d) / deltas.Count;
        }

        return (running, totals, average);
    }
}

using UnityEngine;
using System.Collections.Generic;

public class ProjectilePool : MonoBehaviour
{
    [SerializeField] private GameObject prefab;
    [SerializeField] private int prewarmCount;

    private Queue<GameObject> _pool = new Queue<GameObject>();
    private HashSet<GameObject> _inPool = new HashSet<GameObject>();

    private void Awake()
    {
        for (int i = 0; i < prewarmCount; i++)
        {
            CreateNewInstance();
        }
    }

    private GameObject CreateNewInstance()
    {
        GameObject instance = Instantiate(prefab, transform);
        instance.SetActive(false);
        _pool.Enqueue(instance);
        _inPool.Add(instance);
        return instance;
    }

    public GameObject Rent()
    {
        GameObject instance;

        if (_pool.Count > 0)
        {
            instance = _pool.Dequeue();
            _inPool.Remove(instance);
        }
        else
        {
            // Instantiate a new one if the pool is empty
            // We don't add it to _inPool here because it's immediately being "rented"
            // but we need to track it so Return() knows it's valid.
            // Actually, the simplest way is to create it, then treat it as active.
            instance = Instantiate(prefab, transform);
        }

        instance.SetActive(true);
        return instance;
    }

    public void Return(GameObject go)
    {
        if (go == null)
        {
            return;
        }

        // Prevent adding the same object twice
        if (_inPool.Contains(go))
        {
            return;
        }

        go.SetActive(false);
        _pool.Enqueue(go);
        _inPool.Add(go);
    }
}

using System;

public class TelemetrySender
{
    private readonly NetworkManager _networkManager;

    public TelemetrySender(NetworkManager networkManager)
    {
        _networkManager = networkManager;
    }

    public void Send(string opcode, string payload)
    {
        string processedOpcode = opcode;
        if (processedOpcode.Length > 8)
        {
            processedOpcode = processedOpcode.Substring(0, 8);
        }

        string frame = _networkManager.Encode(processedOpcode, payload);
        _networkManager.Enqueue(frame);
    }
}

public static class FrameUtil
{
    public static int CountZeroes(FrameBuffer buffer)
    {
        int count = 0;
        for (int i = 0; i < buffer.Count; i++)
        {
            if (buffer.Get(i) == 0)
            {
                count++;
            }
        }
        return count;
    }
}
